# Let's manually examine the inputs and outputs to understand the pattern
inputs = ['uufhug', 'ia', 'uijdi', 'awygz', 'hcwcfh']
outputs = ['uufwixg', 'ia', 'uijdi', 'awygz', 'hcwcuhu']

print("Inputs:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}'")

print("\nOutputs:")
for i, out in enumerate(outputs):
    print(f"  {i}: '{out}'")

print("\nDifferences:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"  {i}: '{inp}' -> '{out}'")

